import json
from riboflow.web.server import get_metadata_payload, handle_api_post

def _pyodide_dispatch(method, full_path, body_str):
    path = full_path.split("?", 1)[0].rstrip("/")
    if method.upper() == "GET" and path == "/api/meta":
        return json.dumps({"status": 200, "content_type": "application/json; charset=utf-8", "body": json.dumps(get_metadata_payload())})
    if method.upper() == "POST":
        payload = json.loads(body_str) if body_str else {}
        status, data = handle_api_post(path, payload)
        return json.dumps({"status": int(status), "content_type": "application/json; charset=utf-8", "body": json.dumps(data)})
    return json.dumps({"status": 404, "content_type": "application/json; charset=utf-8", "body": json.dumps({"error": f"Unknown route: {method} {path}"})})
